UPDATE performance_schema.setup_instruments SET ENABLED = 'YES', TIMED = 'YES'
WHERE (NAME LIKE 'statement/%')
   OR NAME IN ('wait/io/table/sql/handler', 'wait/lock/metadata/sql/mdl');
UPDATE performance_schema.setup_consumers SET ENABLED = 'YES'
WHERE NAME IN ('global_instrumentation', 'thread_instrumentation', 'statements_digest',
      'events_statements_current', 'events_statements_history');

UPDATE performance_schema.setup_instruments SET ENABLED = 'YES', TIMED = 'YES'
WHERE NAME LIKE 'wait/%';
UPDATE performance_schema.setup_consumers SET ENABLED = 'YES'
WHERE NAME = 'global_instrumentation';

UPDATE performance_schema.setup_instruments SET ENABLED = 'NO', TIMED = 'NO'
WHERE NAME LIKE 'wait/synch/%' OR NAME LIKE 'wait/io/socket/%'
   OR NAME IN ('wait/lock/metadata/sql/mdl', 'transaction');
UPDATE performance_schema.setup_instruments SET ENABLED = 'YES', TIMED = 'YES'
WHERE NAME LIKE 'wait/io/file/%' OR NAME LIKE 'statement/%'
   OR NAME IN ('wait/io/table/sql/handler', 'wait/lock/table/sql/handler', 'idle');
UPDATE performance_schema.setup_instruments SET ENABLED = 'NO', TIMED = 'NO'
WHERE NAME LIKE 'stage/%' AND NAME NOT IN ('stage/sql/copy to tmp table', 'stage/innodb/alter table (end)', 'stage/innodb/alter table (insert)', 'stage/innodb/alter table (log apply index)', 'stage/innodb/alter table (log apply table)', 'stage/innodb/alter table (merge sort)', 'stage/innodb/alter table (read PK and internal sort)', 'stage/innodb/buffer pool load');
UPDATE performance_schema.setup_instruments SET ENABLED = 'YES', TIMED = 'YES'
WHERE NAME IN ('stage/sql/copy to tmp table', 'stage/innodb/alter table (end)', 'stage/innodb/alter table (insert)', 'stage/innodb/alter table (log apply index)', 'stage/innodb/alter table (log apply table)', 'stage/innodb/alter table (merge sort)', 'stage/innodb/alter table (read PK and internal sort)', 'stage/innodb/buffer pool load');
UPDATE performance_schema.setup_instruments SET ENABLED = 'NO' WHERE NAME LIKE 'memory/%';
UPDATE performance_schema.setup_consumers
   SET ENABLED = IF(NAME IN ('global_instrumentation', 'thread_instrumentation', 'statements_digest'), 'YES', 'NO');
